/* ClearSight V2.8 — decision-oriented reporting. All charts use the source read
 * models. Published reports use captured data only; navigation never refreshes
 * them. Management questions are proposed agenda items, not approved decisions. */
'use strict';

const BR_VIEWS=[['Executive brief','executive'],['Locations','locations'],['Loss drivers','drivers'],['Branch KRIs','kri'],['Assurance & actions','assurance'],['Third party & privacy','dependencies'],['Data confidence','quality'],['Report library','library']];
const brNum=n=>Number.isFinite(Number(n))?num(Number(n)):'—';
const brPercent=(n,d)=>d>0?(100*n/d).toFixed(0)+'%':'—';
const brDate=d=>d?date(d):'Not set';
const brSource=(route,label='Open source')=>route?link(label,route,'small'):'—';
const brRiskScore=r=>Array.isArray(r?.residual)?score(r.residual):0;
const brScopeName=(x,id)=>x.board?.scopeNames?.[id]||id||'Unassigned';
const brTotal=(x,key)=>Number(x?.losses?.[key])||0;
function brMetricFormat(m,value){
 if(value===null||value===undefined||!Number.isFinite(Number(value)))return 'Not reported';
 if(m.type==='money'||m.type==='currency'||/NGN|kobo|₦/i.test(m.unit||m.nativeUnit||''))return ngn(value);
 if(m.type==='ratio'||m.aggregation==='ratio-of-sums')return Number(value).toFixed(2)+'%';
 if(m.aggregation==='exceptions')return brNum(value)+' exceptions';
 if(m.type==='boolean'||m.type==='yesno')return value===1?'Yes':value===0?'No':brNum(value);
 return brNum(value)+(m.unit&&m.unit!=='count'?' '+m.unit:'');
}
function brKriDefinitionSignature(metrics){return recStable([...metrics].sort((a,b)=>String(a.id).localeCompare(String(b.id))));}
function brCaptureTrend(c,scope){
 const units=ixExpected(c,scope),signature=brKriDefinitionSignature(c.metrics);
 return S.branchKri.cycles.filter(z=>z.period<=c.period&&z.definitionVersion===c.definitionVersion&&brKriDefinitionSignature(z.metrics)===signature&&units.every(u=>z.population.includes(u)))
  .sort((a,b)=>a.period.localeCompare(b.period)).slice(-6).map(z=>{const bands=units.flatMap(u=>z.metrics.map(m=>ixBand(m,ixAccepted(z,u)?.values[m.id])));return {id:z.id,period:z.period,approved:units.filter(u=>ixAccepted(z,u)).length,expected:units.length,known:bands.filter(b=>!['Unknown','Not applicable'].includes(b)).length,expectedValues:units.length*z.metrics.length,notApplicable:bands.filter(b=>b==='Not applicable').length,breaches:bands.filter(b=>b==='Breached').length,metrics:z.metrics.map(m=>({id:m.id,name:m.name,type:m.type,unit:m.unit,aggregation:m.aggregation,...ixAggregate(z,m,units)}))};});
}
const brPreviousReportData=reportData;
reportData=function(){
 const x=brPreviousReportData();if(!S.branchKri)return x;
 const scope=selectedScope(),c=ixCycle(),s=ixSummary(),loc=ixLocationRows(),n=scopePeriod(),size=Math.ceil(n/6),trend=[];
 for(let i=5;i>=0;i--){const from=i*size,to=Math.min(n,(i+1)*size);if(from<n)trend.push({from:addDays(S.asOf,1-to),to:addDays(S.asOf,-from),...scopeTotals(ixLossPeriod(to-from,scope,from))});}
 const tasks=ixOpenTasks(),evidence=scopeItems('evidence'),programs=scopeItems('programs'),engagements=scopeItems('engagements');
 const captured={version:'2.8',scopeId:scope,scopeNames:Object.fromEntries(ORG.map(o=>[o.id,orgName(o.id)])),locations:{kind:loc.kind,rows:loc.rows.map(z=>({id:z.node.id,name:z.node.name,risks:z.risks.length,above:z.risks.filter(r=>brRiskScore(r)>r.appetite).length,loss:clone(z.loss),approved:z.kri.approved,expected:z.kri.expected,known:z.kri.known,expectedValues:z.kri.expectedValues,breaches:z.kri.breaches,overdue:z.overdue}))},
  lossTrend:trend,priorLoss:{...scopeTotals(ixLossPeriod(n,scope,n)),from:addDays(S.asOf,1-2*n),to:addDays(S.asOf,-n)},lossDrivers:ixLossGroups().map(g=>({id:g.id,name:g.label,net:g.net,gross:g.gross,recovered:g.recovered,actual:g.actual,near:g.near,above:g.above,risks:g.risks.length})),
  kriDefinition:{version:c.definitionVersion,templateVersion:c.templateVersion||null,metrics:clone(c.metrics),groups:clone(c.groups||[]),population:ixExpected(c,scope),owners:clone(c.owners),reviewer:c.reviewer},kriTrend:brCaptureTrend(c,scope),
  kriObservations:(x.kri.values||[]).map(v=>{const m=c.metrics.find(z=>z.id===v.metric)||{},raw=ixAccepted(c,v.unit)?.values[v.metric]||{};return {...clone(v),name:m.name||v.metric,type:m.type,unitLabel:m.unit,warning:m.warning,limit:m.limit,direction:m.direction,aggregation:m.aggregation,detail:clone(raw.detail||{}),comment:raw.comment||'',owner:raw.detail?.owner||c.owners[v.unit],due:raw.detail?.due||'',action:raw.detail?.action||'',notApplicable:Boolean(raw.notApplicable||raw.na)};}),
  quality:{evidence:evidence.length,currentEvidence:evidence.filter(v=>evQuality(v)==='Current').length,acceptedCurrentEvidence:evidence.filter(v=>v.status==='Accepted'&&evQuality(v)==='Current').length,staleEvidence:evidence.filter(v=>evQuality(v)==='Needs refresh').length,indicatorCount:s.ind.length,currentIndicators:s.ind.filter(v=>!['Unknown','Needs refresh'].includes(indicatorState(v))).length,staleIndicators:s.ind.filter(v=>indicatorState(v)==='Needs refresh').length,unknownIndicators:s.ind.filter(v=>indicatorState(v)==='Unknown').length},
  programContext:programs.map(p=>({id:p.id,owner:p.owner,reviewer:p.reviewer,due:p.due})),dependencies:{engagements:clone(engagements),vendors:clone(S.vendors.filter(v=>engagements.some(z=>z.vendorId===v.id))),processing:scopeItems('processing').length,dpiasOpen:scopeItems('dpias').filter(z=>z.state!=='Approved').length,casesOpen:scopeItems('privacyCases').filter(z=>z.state!=='Closed').length},
  actionAge:{overdue30:tasks.filter(t=>t.due&&days(S.asOf,t.due)>30).length,overdue8:tasks.filter(t=>t.due&&days(S.asOf,t.due)>7&&days(S.asOf,t.due)<=30).length,overdue7:tasks.filter(t=>t.due&&days(S.asOf,t.due)>0&&days(S.asOf,t.due)<=7).length,upcoming:tasks.filter(t=>t.due&&t.due>=S.asOf).length,undated:tasks.filter(t=>!t.due).length}};
 x.reportVersion='2.8';x.board=captured;return x;
};

function brContext(x,frozen=false){return `<section class="br-context" aria-label="Report context"><div><span class="br-kicker">${frozen?'Captured report':'Live scoped view'}</span><strong>${e(x.organization)} · ${e(x.scope?.label||'Bank')}</strong></div><dl><div><dt>Risk posture</dt><dd>${brDate(x.asOf)}</dd></div><div><dt>Loss occurrences</dt><dd>${brDate(x.periods?.loss?.from)}–${brDate(x.periods?.loss?.to)}</dd></div><div><dt>KRI return period</dt><dd>${x.periods?.kri?.month?ixMonthName(x.periods.kri.month):'Not available'}</dd></div></dl></section>`;}
function brBars(rows,{format=brNum,label='Comparison',tone='blue',details=true,emptyText='No observations in this scope.'}={}){
 if(!rows.length)return `<p class="pad br-muted">${e(emptyText)}</p>`;
 const max=Math.max(1,...rows.map(r=>Number(r.value)||0));
 return `<figure class="br-chart" aria-label="${e(label)}"><div class="br-bars">${rows.map(r=>`<div class="br-bar"><div class="br-bar-label">${r.route?`<a href="#/${e(r.route)}">${e(r.label)}</a>`:`<strong>${e(r.label)}</strong>`}${r.note?`<small>${e(r.note)}</small>`:''}</div><div class="br-bar-track" aria-hidden="true"><i class="${e(r.tone||tone)}" style="width:${Math.max(0,Number(r.value)||0)/max*100}%"></i></div><b>${e(format(r.value))}</b></div>`).join('')}</div>${details?`<details class="br-chart-data"><summary>View chart data</summary>${table(['Category','Value','Context'],rows.map(r=>({cells:[e(r.label),e(format(r.value)),e(r.note||'')]})))}</details>`:''}</figure>`;
}
function brKriCoverage(x){
 const k=x.kri||{},na=k.notApplicable||0,total=k.expectedValues||0,known=k.known||0;
 // V2.8 stats include the entire expected population in unknown; legacy stats
 // counted only explicitly missing approved values, so reconstruct that older
 // snapshot's unreported population from its captured coverage counts.
 const current=x.board?.kriDefinition?.templateVersion==='2.8';
 const unknown=current&&Number.isFinite(k.unknown)?k.unknown:Math.max(0,total-known-na);
 return {known,na,total,unknown,applicable:Number.isFinite(k.applicableExpected)?k.applicableExpected:Math.max(0,total-na)};
}
function brCoverage(x){const k=x.kri||{},v=brKriCoverage(x);return `<figure class="br-coverage" aria-label="Approved KRI observation coverage"><div class="br-coverage-number"><strong>${brPercent(v.known+v.na,v.total)}</strong><span>observations accounted for</span></div><div class="br-stack" aria-hidden="true"><i class="teal" style="width:${v.total?v.known/v.total*100:0}%"></i><i class="blue" style="width:${v.total?v.na/v.total*100:0}%"></i><i class="amber" style="width:${v.total?v.unknown/v.total*100:0}%"></i></div><figcaption><span><i class="teal"></i>${v.known} known</span><span><i class="blue"></i>${v.na} approved N/A</span><span><i class="amber"></i>${v.unknown} unreported / unknown</span></figcaption><p>${k.approved||0} of ${k.expected||0} expected reporting locations have an approved return. ${v.known} of ${v.applicable} applicable observations are known; ${v.na} approved N/A are excluded from that denominator and from numeric aggregates.</p></figure>`;}

function brLossChart(x){const bins=x.board?.lossTrend;if(!bins?.length)return `<div class="pad br-muted">This snapshot has no captured loss time series.</div>`;const max=Math.max(1,...bins.map(b=>b.gross));return `<figure class="br-chart"><div class="br-legend"><span><i class="blue"></i>Gross recorded loss</span><span><i class="teal"></i>Recovered through snapshot</span></div><div class="br-columns" role="img" aria-label="Gross loss and associated recoveries by occurrence interval">${bins.map(b=>`<div class="br-column"><b>${moneyShort(b.gross)}</b><div class="br-column-tracks"><i class="blue" style="height:${b.gross/max*130}px"></i><i class="teal" style="height:${b.recovered/max*130}px"></i></div><span>${brDate(b.from).replace(' '+String(x.asOf).slice(0,4),'')}</span></div>`).join('')}</div><details class="br-chart-data"><summary>View chart data</summary>${table(['Occurrence interval','Gross','Recovered','Net','Actual events'],bins.map(b=>({cells:[`${brDate(b.from)}–${brDate(b.to)}`,ngn(b.gross),ngn(b.recovered),ngn(b.net),b.actual]})))}</details></figure>`;}
function brHeatmap(risks){const cells=[];for(let l=5;l>=1;l--)for(let i=1;i<=5;i++){const rs=risks.filter(r=>r.residual?.[0]===l&&r.residual?.[1]===i);cells.push({l,i,rs});}return `<figure class="br-heat-figure"><div class="br-heatmap" role="img" aria-label="Current approved residual risk distribution. Likelihood from five at top to one at bottom, impact from one at left to five at right.">${cells.map(c=>`<div class="br-heat-cell ${c.l*c.i>=15?'high':c.l*c.i>=8?'mid':'low'}" title="Likelihood ${c.l} × impact ${c.i}: ${c.rs.length} risks${c.rs.length?' — '+e(c.rs.map(r=>r.title).join('; ')):''}"><small>${c.l} × ${c.i}</small><strong>${c.rs.length||'–'}</strong></div>`).join('')}</div><figcaption>Likelihood ↑ · Impact → · cell labels are risk counts. Colours show rating bands; each risk retains its own appetite.</figcaption><details class="br-chart-data"><summary>View risk positions</summary>${table(['Risk','Likelihood','Impact','Rating','Appetite'],risks.map(r=>({cells:[e(r.title),r.residual?.[0]||'—',r.residual?.[1]||'—',brRiskScore(r),r.appetite]})))}</details></figure>`;}
function brComparison(x){const p=x.board?.priorLoss;if(!p)return 'Prior-period comparison was not captured.';const change=brTotal(x,'net')-p.net;return `${change===0?'No change in recorded net loss':`${change>0?'Increase':'Decrease'} of ${ngn(Math.abs(change))}`} versus the previous ${x.periods.loss.days}-day occurrence window (${ngn(p.net)}). Collection completeness is not established for either window.`;}
function brDecisionItems(x){
 const out=[],records=x.sourceRecords||{},asOf=x.asOf,k=x.kri||{};
 for(const r of [...(records.risks||[])].filter(r=>brRiskScore(r)>r.appetite).sort((a,b)=>(brRiskScore(b)-b.appetite)-(brRiskScore(a)-a.appetite))){const t=(records.actions||[]).filter(t=>t.ref===r.id).sort((a,b)=>String(a.due||'9999').localeCompare(String(b.due||'9999')))[0];out.push({key:'risk:'+r.id,type:'Appetite exception',title:r.title,why:`Residual ${brRiskScore(r)} exceeds appetite ${r.appetite}; ${r.impact||'the risk remains outside the approved boundary'}.`,ask:t?`Confirm the treatment is adequate and hold ${t.owner} to the recorded action.`:'Request a costed treatment plan or an explicitly authorised, time-bound risk acceptance.',owner:r.owner,due:t?.due||'',action:t?.title||'No linked open treatment action',sourceRoute:'risk?id='+r.id,sourceType:'risk',sourceId:r.id,orgScopeId:r.orgScopeId,tone:'red',taskId:t?.id});}
 for(const v of x.board?.kriObservations||[]){if(v.band!=='Breached')continue;out.push({key:'kri:'+v.unit+':'+v.metric,type:'KRI exception',title:v.name,why:`${brScopeName(x,v.unit)} · ${brMetricFormat({type:v.type,unit:v.unitLabel,aggregation:v.type==='boolean'?null:v.aggregation},v.value)}. ${v.detail.impact||v.detail.summary||v.comment||'Approved observation outside its configured condition.'}`,ask:v.action?`Confirm the corrective action and the owner’s recovery date.`:'Ask the reporting owner for cause, customer or financial impact and a dated corrective action.',owner:v.owner||'Not assigned',due:v.due||'',action:v.action||'Corrective action not yet recorded',sourceRoute:ixReturnRoute(ixReturnKey(x.periods.kri.cycleId,v.unit)),sourceType:'kriReturn',sourceId:ixReturnKey(x.periods.kri.cycleId,v.unit),orgScopeId:v.unit,tone:'red'});}
 if((k.expected||0)>(k.approved||0)){const n=k.expected-k.approved;out.push({key:'coverage:'+x.periods?.kri?.cycleId,type:'Reporting gap',title:`${n} expected ${n===1?'return is':'returns are'} not approved`,why:`${k.known||0}/${k.expectedValues||0} expected observations are known. Pending or missing values are excluded from accepted totals.`,ask:'Require the outstanding returns and explicitly qualify any conclusion drawn from the partial population.',owner:x.board?.kriDefinition?.reviewer||'Review owner not captured',due:x.periods?.kri?.due||'',action:'Complete collection and independent review',sourceRoute:'kri-returns',sourceType:'',sourceId:'',orgScopeId:x.board?.scopeId||'',tone:'amber'});}
 for(const t of (records.actions||[]).filter(t=>t.due&&t.due<asOf).sort((a,b)=>a.due.localeCompare(b.due))){out.push({key:'action:'+t.id,type:'Overdue commitment',title:t.title,why:`${days(asOf,t.due)} days past the recorded due date.`,ask:'Challenge the delay, confirm recovery date and escalate if the commitment remains at risk.',owner:t.owner,due:t.due,action:'Obtain an updated recovery plan',sourceRoute:'work',sourceType:'task',sourceId:t.id,orgScopeId:t.orgScopeId,tone:'amber',taskId:t.id});}
 return out;
}
function brDecisionTable(x,{live=false,limit=8}={}){const items=brDecisionItems(x);if(!items.length)return empty('No exceptions in the available records','Review the coverage statement before concluding that no intervention is needed.');return `<div class="br-decision-list">${items.slice(0,limit).map((d,i)=>`<article class="br-decision"><span class="br-decision-number ${d.tone}">${String(i+1).padStart(2,'0')}</span><div class="br-decision-content"><div class="br-decision-heading"><span class="br-kicker">${e(d.type)}</span><span class="br-owner">${e(d.owner)} · ${d.due?brDate(d.due):'Due date not set'}</span></div><h3>${e(d.title)}</h3><p>${e(d.why)}</p><div class="br-ask"><strong>Management question</strong><span>${e(d.ask)}</span></div><small>Current action: ${e(d.action)}</small>${live?`<div class="br-decision-actions">${d.taskId?btn('Review existing action','task-detail',`data-id="${e(d.taskId)}"`,'small'):brSource(d.sourceRoute)}${d.sourceType&&d.sourceType!=='task'&&!d.taskId?btn('Assign follow-up','br-followup',`data-key="${e(d.key)}"`,'quiet small'):''}</div>`:''}</div></article>`).join('')}</div>${items.length>limit?`<p class="br-more">${items.length-limit} more exceptions in the underlying registers. ${live?link('Review all source records','reports?view=assurance','quiet small'):''}</p>`:''}`;}
function brSummary(x,view='executive'){
 const risks=x.risk||{},k=x.kri||{},loss=x.losses||{},prior=x.board?.priorLoss,missing=brKriCoverage(x).unknown,locations=x.board?.locations?.rows||[],largest=[...(x.board?.lossDrivers||[])].sort((a,b)=>b.net-a.net)[0];let title='The decisions behind the numbers',copy='';
 if(view==='executive')copy=`${risks.aboveAppetite||0} of ${risks.total||0} registered risks exceed appetite. ${k.breaches||0} approved KRI observations breach their conditions; ${missing} observations are not yet known or accounted for. ${x.actions?.overdue||0} open actions are overdue.`;
 if(view==='locations'){const top=[...locations].sort((a,b)=>b.loss.net-a.loss.net)[0];title='Where management attention is concentrated';copy=top&&loss.net?`${top.name} accounts for ${brPercent(top.loss.net,loss.net)} of recorded net loss in this scope (${ngn(top.loss.net)}). Compare the risk count, return coverage and overdue commitments before allocating intervention.`:'Location comparisons use recorded losses, approved returns and open actions. No transaction-volume denominator is available for fair performance ranking.';}
 if(view==='drivers'){title='What is driving recorded loss';copy=largest&&loss.net?`${largest.name} contributes ${brPercent(largest.net,loss.net)} of recorded net loss (${ngn(largest.net)}). ${brComparison(x)}`:brComparison(x);}
 if(view==='kri'){title='Exceptions need context and a response';copy=`${k.approved||0}/${k.expected||0} reporting locations approved; ${k.breaches||0} condition breaches across approved observations. ${missing?`${missing} observations are unknown or unreported. `:''}Read each exception with its cause, impact, accountable owner, action and due date.`;}
 if(view==='assurance'){title='Track assurance and delivery separately';copy=`${x.actions?.overdue||0} of ${x.actions?.open||0} open commitments are overdue. ${x.board?.quality?.staleEvidence||0} document reviews need refresh. A submitted return or fresh document does not itself establish that a requirement is satisfied.`;}
 if(view==='dependencies'){const d=x.board?.dependencies;title='Focus on critical services and unresolved reviews';copy=d?`${d.engagements.filter(z=>z.criticality==='Critical').length} critical engagements in the selected scope. ${d.dpiasOpen} impact assessments remain unapproved and ${d.casesOpen} privacy cases remain open. Confirm the service owner’s recovery and assurance arrangements.`:'Dependency context was not captured in this report.';}
 if(view==='quality'){title='What the board can rely on';copy=`${k.known||0} of ${k.expectedValues||0} expected KRI observations are known; ${k.notApplicable||0} are approved N/A. Loss collection completeness and a comparable historical risk-rating series are not established. Keep these limitations beside any conclusion.`;}
 return `<section class="br-brief"><div><span class="br-kicker">${view==='executive'?'Executive reading':'Reading this view'}</span><h2>${e(title)}</h2><p>${e(copy)}</p></div><div class="br-brief-side"><span>Posture at snapshot</span><strong>${risks.aboveAppetite||0} <small>above appetite</small></strong><span>${risks.total||0} registered risks in scope</span></div></section>`;
}
function brHeadline(x){return `<div class="br-metrics"><a href="#/insight-detail?kind=appetite"><span>Outside risk appetite</span><strong>${x.risk.aboveAppetite}<small> / ${x.risk.total}</small></strong><small>Current approved residual ratings</small></a><a href="#/reports?view=drivers"><span>Recorded net loss</span><strong>${moneyShort(x.losses.net)}</strong><small>${x.losses.events} actual events · ${x.periods.loss.days} days</small></a><a href="#/reports?view=kri"><span>KRI condition breaches</span><strong>${x.kri.breaches}<small> observations</small></strong><small>${x.kri.approved}/${x.kri.expected} returns approved</small></a><a href="#/insight-detail?kind=actions"><span>Overdue commitments</span><strong>${x.actions.overdue}<small> / ${x.actions.open}</small></strong><small>Open actions with recorded due dates</small></a></div>`;}
function brKriDisplay(x,{frozen=false}={}){
 const defs=x.board?.kriDefinition?.metrics||[],groupDefs=x.board?.kriDefinition?.groups||[],groups=new Map();
 const columns=['Indicator','Observed result','Reporting coverage','Exceptions / interpretation'];
 const renderRows=items=>table(columns,items.map(m=>{
  const d=defs.find(z=>z.id===m.metric)||m,agg=m.aggregation||d.aggregation,na=m.notApplicable||0,applicable=Number.isFinite(m.applicableExpected)?m.applicableExpected:Math.max(0,m.expected-na),unknown=Math.max(0,applicable-m.observed);
  return {cells:[`<strong>${e(m.name)}</strong><small>${e(d.type||'observation')}</small>`,agg==='context'?'<span class="br-muted">Context only</span>':`<strong>${e(brMetricFormat({...d,aggregation:agg},m.value))}</strong>${m.denominator!=null?`<small>${brNum(m.numerator)} / ${brNum(m.denominator)}</small>`:''}`,`${m.observed}/${applicable} applicable locations<small>${na} approved N/A · ${unknown} unknown / unreported</small>`,`${m.breaches?pill(m.breaches+' condition breaches','red'):agg==='context'?pill('Context only'):pill(m.complete?'No observed breach':'Partial coverage',m.complete?'green':'amber')}<small>${agg==='ratio-of-sums'?'Weighted by the underlying denominator':agg==='sum'?'Sum of valid values; no aggregate appetite assumed':agg==='exceptions'?'Count of locations meeting exception condition':'Inspect the source return for context'}</small>`]};
 }));
 const all=x.kri.consolidation||[];
 if(all.length<=8)return renderRows(all);
 for(const m of all){const d=defs.find(z=>z.id===m.metric)||m,id=d.group||d.category||'other';if(!groups.has(id))groups.set(id,{id,name:groupDefs.find(g=>g.id===id)?.name||id,items:[]});groups.get(id).items.push(m);}
 return `<div class="br-kri-register"><p class="br-kri-register-note">${all.length} indicators in ${groups.size} categories. Categories with recorded breaches are expanded${frozen?'; all details are included in this published pack':''}. Open a category to inspect its observations.</p>${[...groups.values()].map(g=>{
  const breaches=g.items.reduce((n,m)=>n+(m.breaches||0),0),unknown=g.items.reduce((n,m)=>n+Math.max(0,m.expected-m.observed-(m.notApplicable||0)),0);
  return `<details class="br-kri-group" ${frozen||breaches?'open':''}><summary><span><strong>${e(g.name)}</strong><small>${g.items.length} indicators · ${unknown} unknown / unreported observations</small></span>${pill(breaches?breaches+' breaches':unknown?'Partial coverage':'No observed breach',breaches?'red':unknown?'amber':'green')}</summary><div class="br-kri-group-body">${renderRows(g.items)}</div></details>`;
 }).join('')}</div>`;
}

function brKriTrend(x){const all=x.board?.kriTrend||[];if(all.length<2)return panel('Comparable KRI history','A trend requires the same definitions and reporting population.',`<div class="pad br-muted">${all.length?'One comparable period is captured.':'No comparable history is captured.'} A trend is not inferred from different questions, populations or unapproved observations.</div>`);return panel('KRI history with reporting coverage','Matching definitions and the same location cohort. Changes in coverage can change observed exception counts.',brBars(all.map(v=>({label:ixMonthName(v.period),value:v.breaches,note:`${v.approved}/${v.expected} approved returns · ${v.known}/${v.expectedValues} values known`,tone:'red'})),{label:'KRI exceptions over comparable reporting periods',format:n=>n+' breaches'})+table(['Period','Returns approved','Known observations','Approved N/A','Condition breaches'],all.map(v=>({cells:[ixMonthName(v.period),`${v.approved}/${v.expected}`,`${v.known}/${v.expectedValues}`,v.notApplicable,v.breaches]}))));}
function brQualityPanel(x){const q=x.board?.quality||{},k=x.kri||{},v=brKriCoverage(x),rows=[{label:'Approved KRI returns',value:k.approved||0,total:k.expected||0},{label:'Known applicable KRI observations',value:v.known,total:v.applicable},{label:'Approved N/A observations',value:v.na,total:v.total,context:true},{label:'Current continuous indicators',value:q.currentIndicators||0,total:q.indicatorCount||0},{label:'Accepted current document reviews',value:q.acceptedCurrentEvidence||0,total:q.evidence||0}];return panel('Data available for this conclusion','Applicable KRI coverage excludes approved N/A. Each other measure retains its own denominator.',`<div class="br-quality-rows">${rows.map(r=>`<div><span>${r.label}${r.context?'<small class="br-muted">Excluded from applicable coverage</small>':''}</span><div class="br-quality-track ${r.context?'br-context-track':''}" aria-hidden="true"><i style="width:${r.total?r.value/r.total*100:0}%"></i></div><b>${r.value}/${r.total}</b></div>`).join('')}</div><div class="br-quality-note"><strong>${v.unknown} KRI observations unknown or unreported</strong><p>Missing and pending data remain gaps. Approved N/A is accounted for and does not become a failed or unknown observation.</p><strong>Loss collection completeness: not established</strong><p>Zero recorded loss is not a certified nil-loss return. The dashboard covers the available operational-risk and assurance records.</p></div>`);}
function brQualityDetails(x){const v=brKriCoverage(x),q=x.board?.quality||{},unscoped=(x.sourceRecords?.risks||[]).filter(r=>!r.orgScopeId).length;return panel('What limits the interpretation','Resolve these gaps before presenting a result as comprehensive assurance.',table(['Dataset','Observed limitation','Effect on the conclusion','Action'],[
 {cells:['Periodic KRI returns',`${x.kri.expected-x.kri.approved} expected returns not approved; ${v.unknown} observations unknown or unreported`,`${v.known}/${v.applicable} applicable observations known; ${v.na} approved N/A shown separately.`,link('Review returns','kri-returns','small')]},
 {cells:['Continuous indicators',`${q.staleIndicators||0} stale; ${q.unknownIndicators||0} unknown`,'Old or missing observations do not become green.',link('Inspect indicators','indicators','small')]},
 {cells:['Risk inventory',unscoped?`${unscoped} scoped records have no assigned location`:'Captured risk records have locations','Inventory completeness is not independently established.',link('Risk register','risks','small')]},
 {cells:['Recorded losses','No certified collection completeness or nil returns','No recorded event is not proof that no loss occurred.',link('Loss events','losses','small')]},
 {cells:['Historical ratings','No comparable approved series for the full inventory','Current rating charts do not imply a movement in risk.',link('RCSA decisions','rcsa','small')]},
 {cells:['Exposure-normalised losses','No complete revenue or transaction denominator for the same window','Absolute branch loss cannot establish comparative management performance.','Additional governed source required']},
 {cells:['Full bank risk universe','Credit, market, liquidity and capital feeds are absent','The available view covers operational risk and assurance.','Additional governed source required']}
 ]))+`<details class="panel br-method"><summary>Calculation definitions and source traceability</summary><div class="pad"><p><strong>Period losses:</strong> event occurrence within the stated window; recoveries through the snapshot for those same events. Each event once, integer kobo, no inferred FX conversion.</p><p><strong>Applicable KRI coverage:</strong> known approved observations / (expected observations minus approved N/A). Pending and unknown answers remain in the denominator. A separate N/A count preserves the full expected population.</p><p><strong>Ratios:</strong> sum of valid numerators / sum of their matching denominators. Boolean exception totals count adverse reporting locations; context-only questions carry no appetite conclusion.</p><p><strong>Risk appetite:</strong> the current approved likelihood × impact rating compared with that risk’s own appetite. Ratings are not currency or probabilities.</p><p><strong>Program results:</strong> retain the assessed target, preventing shared programs from becoming unsupported branch-level conclusions.</p></div></details>`;}

function brActionAge(x){const a=x.board?.actionAge;if(!a)return '';return panel('Age of open commitments','Days from recorded due date to the report snapshot.',brBars([{label:'Overdue >30 days',value:a.overdue30,tone:'red'},{label:'Overdue 8–30 days',value:a.overdue8,tone:'red'},{label:'Overdue 1–7 days',value:a.overdue7,tone:'amber'},{label:'Due today / later',value:a.upcoming,tone:'blue'},{label:'No due date',value:a.undated,tone:'amber'}],{label:'Age of open action commitments'}));}
function brAssuranceChart(x){const rows=x.programs.flatMap(p=>p.targets.map(t=>({label:p.name+' · '+t.name,value:t.pass,total:t.all,reviewed:t.reviewed,note:`${t.pass}/${t.all} satisfied · ${t.reviewed}/${t.all} reviewed`,route:'program?id='+p.id+'&target='+encodeURIComponent(t.id)})));return panel('Satisfied requirements by actual assessment target','Targets retain their own denominator and assurance boundary.',brBars(rows,{label:'Satisfied requirements by assessment target',format:n=>n+' satisfied'}));}
function brExecutive(x){return brSummary(x)+brHeadline(x)+`<div class="br-executive-grid">${panel('Priority management questions','Suggested agenda from recorded exceptions. Decisions require the appropriate authority.',brDecisionTable(x,{live:true,limit:5}),btn('Prepare board pack','ix-new-report','','primary small'))}<div class="br-stack-panels">${panel('KRI reporting confidence','Approved observations and explicit gaps.',brCoverage(x),link('Inspect coverage','reports?view=quality','quiet small'))}${panel('Loss concentration','Net recorded loss by risk category.',brBars((x.board?.lossDrivers||[]).filter(d=>d.net).map(d=>({label:d.name,value:d.net,note:d.actual+' actual events',route:'insight-detail?kind=category&id='+encodeURIComponent(d.id)})),{format:moneyShort,label:'Net loss by risk category',details:false}))}</div></div><div class="br-two">${panel('Current residual risk distribution','Approved ratings at the snapshot; no historical rating movement is inferred.',brHeatmap(x.sourceRecords.risks))}${panel('Loss occurrence and recovery','NGN · each event counted once in its occurrence interval.',brLossChart(x))}</div>`;}

reportsView=function(){
 const view=BR_VIEWS.some(v=>v[1]===current.params.get('view'))?current.params.get('view'):BR_VIEWS.some(v=>v[1]===S.insightView)?S.insightView:'executive';S.insightView=view;
 const x=reportData();let body='';
 if(view==='executive')body=brExecutive(x);
 if(view==='locations')body=brSummary(x,view)+ixLocations();
 if(view==='drivers')body=brSummary(x,view)+`<div class="br-two">${panel('Recorded loss over time','Gross losses and recoveries, grouped by event occurrence.',brLossChart(x))}${panel('Current and prior windows','Adjacent windows of equal length; recoveries through the same snapshot.',brBars([{label:'Current window',value:x.losses.net,note:`${brDate(x.periods.loss.from)}–${brDate(x.periods.loss.to)}`},{label:'Previous window',value:x.board.priorLoss.net,note:`${brDate(x.board.priorLoss.from)}–${brDate(x.board.priorLoss.to)}`}],{format:ngn,label:'Current and prior net recorded losses'}))}</div>`+ixDrivers();
 if(view==='kri')body=brSummary(x,view)+`<div class="br-two">${panel('Return coverage','Only approved snapshots feed the results.',brCoverage(x),link('Collect and review returns','kri-returns','small'))}${panel('Interpret the aggregate','Observe breaches at their accountable reporting location.',`<div class="pad"><p>Counts and monetary values retain their units. A total does not inherit an individual branch’s threshold.</p><p>Boolean exceptions are counted by location. Context questions and approved N/A remain separate from measured thresholds.</p><p>Ratios use the sum of numerators divided by the sum of denominators.</p>${link('Open detailed returns','kri-returns','small')}</div>`)}</div>`+panel('KRI results and reporting coverage',`${e(x.periods.kri.definitionVersion)} · ${ixMonthName(x.periods.kri.month)}`,brKriDisplay(x))+panel('Exceptions and missing responses','The impact and remediation recorded by the accountable location.',brDecisionTable({...x,sourceRecords:{...x.sourceRecords,risks:[],actions:[]}},{live:true,limit:12}))+brKriTrend(x);
 if(view==='assurance')body=brSummary(x,view)+`<div class="br-two">${brAssuranceChart(x)}${brActionAge(x)}</div>`+ixAssurance();
 if(view==='dependencies')body=brSummary(x,view)+ixDependencies();
 if(view==='quality')body=brSummary(x,view)+brQualityPanel(x)+brQualityDetails(x);
 if(view==='library')body=ixSavedReports();
 return header('Reports & insights','A clear view of exceptions, impact, accountability and the decisions required.',btn('Save live view','ix-save-view')+' '+btn(icon('download')+' Export source data','report-export')+' '+btn('Prepare board pack','ix-new-report','','primary'),'Management intelligence')+`<div class="ix-report-tools">${scopePeriodControl()}${ixCycleSelect()}<div class="grow"></div>${btn('Export briefing CSV','br-export-brief','','quiet small')}${btn('Print this view','print','','quiet small')}</div>`+brContext(x)+tabLinks(BR_VIEWS.map(([label,id])=>[label,'reports?view='+id,id]),view)+`<div class="br-report-content">${body}</div>`;
};

const brPriorDetailView=ixDetailView;
function brDetailView(){const d=ixDetailData(),totals=scopeTotals(d.losses),x=reportData();let insight='';if(d.kind==='actions')insight=panel('What needs management intervention',`${d.tasks.length} overdue commitments. Confirm an accountable owner and recovery date for each.`,brActionAge(x));else{const above=d.risks.filter(r=>brRiskScore(r)>r.appetite);insight=`<section class="br-brief"><div><span class="br-kicker">Source-level interpretation</span><h2>${above.length} risk exceptions · ${moneyShort(totals.net)} recorded net loss</h2><p>${e(d.label)} contains ${d.risks.length} current risks and ${totals.actual} actual loss events in the selected occurrence window. ${above.length?'Review whether the treatment actions address the risks still outside appetite.':'No above-appetite risk appears in these source records.'}</p></div></section><div class="br-two">${panel('Residual ratings and appetite','This source population only.',brBars(d.risks.map(r=>({label:r.title,value:brRiskScore(r),note:`Appetite ${r.appetite} · ${r.owner}`,tone:brRiskScore(r)>r.appetite?'red':'teal',route:'risk?id='+r.id})),{label:'Residual ratings within this source population'}))}${panel('Recorded net loss by event','Each event once; recoveries through the snapshot.',brBars(d.losses.map(l=>({label:l.title,value:l.gross-recoveries(l),note:brDate(l.date),route:'loss?id='+l.id})),{label:'Net loss by source event',format:moneyShort}))}</div>`;}
 const base=brPriorDetailView();const markers=['<section class="metrics','<div class="metrics'];const idx=markers.map(m=>base.indexOf(m)).find(i=>i>=0)??-1;return idx>=0?base.slice(0,idx)+insight+base.slice(idx):base+insight;
}

function brEnsureDraft(){const d=S.reportDraft;if(!d)return null;d.decisions??=[];d.meetingDate??=addDays(d.snapshot.asOf,7);d.preparedBy??=typeof recActor==='function'?recActor().name:'Demo operator';d.coverageAcknowledged??=false;return d;}
function brPackDecisionRows(p){const rows=p.decisions||[];return rows.length?table(['Decision / request','Type','Accountable owner','Target date','Source'],rows.map(d=>({cells:[`<strong>${e(d.title)}</strong><small>${e(d.rationale)}</small>`,e(d.kind),e(d.owner),brDate(d.due),e(d.sourceId||'Management item')]}))):`<div class="pad br-muted">No explicit decisions were entered by the report author. The exception agenda below remains a set of management questions.</div>`;}
function brFrozenBody(p){const x=p.snapshot,sections=p.sections||[],has=s=>sections.includes(s),parts=[];
 parts.push(brContext(x,true));
 parts.push(`<div class="br-pack-title"><div><span class="br-kicker">${e(p.audience)}</span><h2>${e(p.name)}</h2><p>Prepared by ${e(p.preparedBy||'Report author')} · Meeting ${brDate(p.meetingDate)} · Captured ${e(recTimestamp(x.generatedAt))}</p></div>${pill('Frozen snapshot','blue')}</div>`);
 parts.push(brSummary(x));
 parts.push(panel('Decisions requested by management','Recorded by the report author. Publication does not constitute approval or create an operational action.',brPackDecisionRows(p)));
 if(p.commentary)parts.push(panel('Management assessment','Author commentary retained with this snapshot.',`<div class="pad br-commentary">${e(p.commentary)}</div>`));
 parts.push(panel('Priority exception agenda','Generated from the captured source records; proposed questions remain separate from management decisions.',brDecisionTable(x,{limit:8})));
 if(has('risks'))parts.push(`<div class="br-two">${panel('Current risk distribution','Captured approved residual positions.',brHeatmap(x.sourceRecords.risks))}${panel('Appetite exceptions','Rating versus each risk’s approved appetite.',brBars(x.sourceRecords.risks.filter(r=>brRiskScore(r)>r.appetite).map(r=>({label:r.title,value:brRiskScore(r),note:`Appetite ${r.appetite} · ${r.owner}`,tone:'red'})),{label:'Captured appetite exceptions'}))}</div>`+panel('Risk accountability','Every registered risk in the captured scope.',table(['Risk','Residual / appetite','Owner','Disposition'],x.sourceRecords.risks.map(r=>({cells:[`<strong>${e(r.title)}</strong><small>${e(r.impact||'')}</small>`,`${brRiskScore(r)} / ${r.appetite}`,e(r.owner),e(r.status)]})))));
 if(has('losses'))parts.push(`<div class="br-two">${panel('Loss occurrence and recovery','Captured occurrence intervals; NGN.',brLossChart(x))}${panel('Loss concentration','Net loss by category within the captured scope.',brBars((x.board?.lossDrivers||[]).map(v=>({label:v.name,value:v.net,note:v.actual+' actual events'})),{format:moneyShort,label:'Captured loss concentration'}))}</div>`+panel('Loss reconciliation',brComparison(x),table(['Gross recorded loss','Recovered through snapshot','Recorded net loss','Actual events / near misses'],[{cells:[ngn(x.losses.gross),ngn(x.losses.recoveries),ngn(x.losses.net),`${x.losses.events} / ${x.losses.nearMisses}`]}])));
 if(has('kri'))parts.push(panel('Branch KRI coverage','Approved data, explicit N/A and unresolved gaps.',brCoverage(x))+panel('KRI result register','Observed aggregates retain the source metric units and reporting coverage.',brKriDisplay(x,{frozen:true}))+brKriTrend(x));
 if(has('actions'))parts.push(brActionAge(x)+panel('Actions and accountability',`${x.actions.overdue} overdue of ${x.actions.open} open actions at ${brDate(x.asOf)}.`,table(['Commitment','Owner','Due date','State at snapshot'],x.sourceRecords.actions.map(t=>({cells:[e(t.title),e(t.owner),brDate(t.due),t.due&&t.due<x.asOf?'Overdue':t.due?'Open':'Due date missing']})))));
 if(has('assurance'))parts.push(brAssuranceChart(x)+panel('Program assurance by assessment target','Requirements retain their original program and target.',table(['Program / target','Satisfied','Reviewed','Owner / due'],x.programs.flatMap(p=>p.targets.map(t=>{const c=x.board?.programContext?.find(z=>z.id===p.id);return {cells:[`<strong>${e(p.name)}</strong><small>${e(t.name)}</small>`,`${t.pass}/${t.all}`,`${t.reviewed}/${t.all}`,c?`${e(c.owner)}<small>${brDate(c.due)}</small>`:'Not captured']};})))));
 parts.push(brQualityPanel(x));
 parts.push(`<details class="panel br-method" open><summary>Basis, limitations and source references</summary><div class="pad"><p><strong>Three separate clocks:</strong> risk posture at the snapshot, loss occurrence within its stated window, and periodic KRI returns for their own month. Source links below may open later live records; this report remains unchanged.</p>${(x.limitations||[]).map(v=>`<p>${e(v)}</p>`).join('')}<p><strong>Source identifiers:</strong> ${e([...x.sourceRecords.risks.map(r=>r.id),...x.sourceRecords.losses.map(l=>l.id),...new Set((x.kri.values||[]).map(v=>v.submission).filter(Boolean))].join(' · ')||'No records')}</p></div></details>`);
 return `<article class="br-frozen-pack">${parts.join('')}</article>`;
}
ixFrozenBody=brFrozenBody;
function brReportBuilder(){const d=brEnsureDraft();if(!d)return header('Prepare board pack','Capture scope and periods, state decisions, and preview the fixed report.')+empty('No report in preparation','Start from the intended live report view.',btn('Start board pack','ix-new-report','','primary'));let body='';
 if(d.step===1)body=`<span class="br-kicker">Step 1 · Audience and coverage</span><h2>Give the pack a clear purpose</h2><div class="field-grid">${input('name','Report title',d.name,'text','data-ix-report-draft="name" maxlength="140"')}${select('audience','Audience',['Board risk committee','Board of directors','Management risk committee','Branch management','Risk analyst'],d.audience,'data-ix-report-draft="audience"')}${input('meetingDate','Meeting / review date',d.meetingDate,'date','data-br-draft="meetingDate"')}${select('preparedBy','Prepared by',CS_SEED.people,d.preparedBy,'data-br-draft="preparedBy"')}</div><h3>Included sections</h3><div class="ix-population">${IX_SECTIONS.map(([id,label])=>`<label class="checkbox-row"><input type="checkbox" data-ix-report-section="${id}" ${d.sections.includes(id)?'checked':''}>${label}</label>`).join('')}</div><p class="br-muted">The decision agenda and data confidence statement accompany every pack.</p>${brContext(d.snapshot,true)}`;
 if(d.step===2)body=`<span class="br-kicker">Step 2 · Management assessment</span><h2>Make the decisions explicit</h2>${brContext(d.snapshot,true)}${area('commentary','Executive assessment and material changes',d.commentary,'data-ix-report-draft="commentary" placeholder="Explain the material exceptions, business impact, management response and what the committee needs to decide."')}<div class="br-section-heading"><div><h3>Decisions and requests</h3><p>These statements are part of the pack, not automatic approvals or new work items.</p></div>${btn('Add decision','br-add-decision','','small')}</div><div class="br-decision-editor">${d.decisions.map((v,i)=>`<section class="br-decision-edit"><div class="br-section-heading"><strong>Item ${i+1}</strong>${btn('Remove','br-remove-decision',`data-index="${i}"`,'quiet small')}</div><div class="field-grid">${input('decision-title-'+i,'Decision / request',v.title,'text',`data-br-decision="${i}" data-part="title" maxlength="240"`)}${select('decision-kind-'+i,'Decision type',['Note / monitor','Request treatment','Approve resources','Risk acceptance request','Escalate'],v.kind,`data-br-decision="${i}" data-part="kind"`)}${select('decision-owner-'+i,'Accountable owner',CS_SEED.people,v.owner,`data-br-decision="${i}" data-part="owner"`)}${input('decision-due-'+i,'Target date',v.due,'date',`data-br-decision="${i}" data-part="due"`)}${input('decision-source-'+i,'Source record ID',v.sourceId,'text',`data-br-decision="${i}" data-part="sourceId" maxlength="150"`)}</div>${area('decision-rationale-'+i,'Business impact / rationale',v.rationale,`data-br-decision="${i}" data-part="rationale" maxlength="2000"`)}</section>`).join('')||'<p class="br-muted">No explicit decisions yet. Add one or use a suggested exception below.</p>'}</div><details class="panel br-method"><summary>Use a recorded exception as a starting point</summary><div class="pad">${brDecisionItems(d.snapshot).slice(0,12).map((v,i)=>`<div class="br-suggestion"><div><strong>${e(v.title)}</strong><small>${e(v.owner)} · ${e(v.type)}</small></div>${btn('Add to agenda','br-use-suggestion',`data-index="${i}"`,'small')}</div>`).join('')||'<p>No source exceptions found.</p>'}</div></details><label class="checkbox-row"><input type="checkbox" data-br-coverage ${d.coverageAcknowledged?'checked':''}>I have reviewed the reporting coverage and will retain the stated limitations in the pack.</label>`;
 if(d.step===3)body=`<span class="br-kicker">Step 3 · Final review</span><h2>Preview the board pack</h2><p>Publication captures this local report. Operational records, decisions and approvals remain separate.</p>${brFrozenBody(d)}`;
 return header('Prepare board pack','Audience & scope → management assessment → preview and publish.',link('Save & exit','reports?view=library'),'Report preparation')+ixWizardSteps(['Audience & scope','Decisions & assessment','Preview'],d.step,'ix-report-step')+`<section class="panel ix-wizard br-builder"><div class="pad">${body}<div id="ix-report-error" role="alert"></div></div><footer>${d.step>1?btn('Back','ix-report-step',`data-step="${d.step-1}"`):link('Exit builder','reports?view=library')}<span>Captured ${e(recTimestamp(d.snapshot.generatedAt))}</span>${d.step<3?btn('Continue '+icon('arrow'),'ix-report-step',`data-step="${d.step+1}"`,'primary'):btn('Publish snapshot','ix-publish-report','','primary')}</footer></section>`;
}
function brReportPackView(){const p=S.reportPacks.find(z=>z.id===current.params.get('id'));if(!p)return header('Published report','Fixed source snapshot and management commentary.')+empty('Report not found','Open a saved report from the library.',link('Report library','reports?view=library'));return header(e(p.name),`${e(p.audience)} · ${e(p.id)}`,link('Report library','reports?view=library')+' '+btn('Export captured data','ix-export-pack',`data-id="${e(p.id)}"`)+' '+btn('Print / save PDF','print','','primary'),'Published management report')+notice('Frozen report: the scope and figures captured below are authoritative. Current navigation filters and subsequent source changes do not recalculate this pack.','mini')+brFrozenBody(p);}

function brValidDate(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value;}
function brCapturedSourceIds(x){return new Set([...(x.sourceRecords?.risks||[]),...(x.sourceRecords?.losses||[]),...(x.sourceRecords?.actions||[]),...(x.programs||[])].map(v=>v.id).concat((x.kri?.values||[]).map(v=>ixReturnKey(x.periods.kri.cycleId,v.unit))));}
function brDraftIssues(d){
 const issues=[];
 if(!d.name?.trim()||d.name.trim().length<3)issues.push('Enter a report title of at least three characters.');
 if(!d.sections?.length)issues.push('Choose at least one report section.');
 if(!brValidDate(d.meetingDate))issues.push('Set a valid meeting or review date.');
 if(!d.coverageAcknowledged)issues.push('Review and acknowledge the reporting coverage before publishing.');
 const sources=brCapturedSourceIds(d.snapshot);
 for(const [i,v] of (d.decisions||[]).entries()){
  if(String(v.title||'').trim().length<5||String(v.rationale||'').trim().length<10)issues.push(`Decision ${i+1}: enter a clear request and substantive rationale.`);
  if(!CS_SEED.people.includes(v.owner))issues.push(`Decision ${i+1}: choose an accountable owner.`);
  if(!brValidDate(v.due))issues.push(`Decision ${i+1}: set a valid target date.`);
  else if(v.due<d.snapshot.asOf)issues.push(`Decision ${i+1}: target date cannot precede the report snapshot.`);
  if(v.sourceId?.trim()&&!sources.has(v.sourceId.trim()))issues.push(`Decision ${i+1}: source ID must belong to this report’s captured records, or be left blank for a management item.`);
 }
 return issues;
}
function brShowDraftIssues(issues){const el=$('#ix-report-error');if(el){el.innerHTML=notice(issues.map(e).join('<br>'),'warning');el.scrollIntoView({block:'nearest'});}else toast(issues[0]);}
const brPriorReportStep=actions['ix-report-step'],brPriorPublish=actions['ix-publish-report'];
actions['ix-report-step']=el=>{const d=brEnsureDraft(),step=Number(el.dataset.step);if(d&&step===3&&step>d.step){const issues=brDraftIssues(d);if(issues.length){brShowDraftIssues(issues);return;}}brPriorReportStep(el);};
actions['ix-publish-report']=()=>{const d=brEnsureDraft();requireValue(d,'No report in preparation.');const issues=brDraftIssues(d);if(issues.length){brShowDraftIssues(issues);return;}brPriorPublish();};
Object.assign(actions,{
 'br-add-decision':()=>{const d=brEnsureDraft();requireValue(d,'No report draft.');d.decisions.push({title:'',kind:'Request treatment',owner:CS_SEED.people[0],due:addDays(d.snapshot.asOf,14),sourceId:'',rationale:''});save();render();},
 'br-remove-decision':el=>{const d=brEnsureDraft(),i=Number(el.dataset.index);requireValue(d&&Number.isInteger(i)&&d.decisions[i],'Decision not found.');d.decisions.splice(i,1);save();render();},
 'br-use-suggestion':el=>{const d=brEnsureDraft(),v=d&&brDecisionItems(d.snapshot)[Number(el.dataset.index)];requireValue(v,'Exception not found.');requireValue(!d.decisions.some(z=>z.key===v.key),'This exception is already in the decision agenda.');d.decisions.push({key:v.key,title:v.ask,kind:'Request treatment',owner:CS_SEED.people.includes(v.owner)?v.owner:CS_SEED.people[0],due:v.due&&v.due>=d.snapshot.asOf?v.due:addDays(d.snapshot.asOf,7),sourceId:v.sourceId||'',rationale:v.why});save();render();},
 'br-export-brief':()=>{const x=reportData();exportCSV('clearsight-management-brief.csv',['snapshot','scope','kind','exception','why_it_matters','management_question','owner','due','record_id','source_route'],brDecisionItems(x).map(v=>[x.asOf,x.scope.label,v.type,v.title,v.why,v.ask,v.owner,v.due,v.sourceId,v.sourceRoute]));},
 'br-followup':el=>{const x=reportData(),v=brDecisionItems(x).find(z=>z.key===el.dataset.key);requireValue(v&&v.sourceType&&v.sourceType!=='task','This source is no longer available.');const source=recRead(v.sourceType,v.sourceId);requireValue(source&&recInScope(v.sourceType,source),'The source is outside the selected scope.');const originalScope=selectedScope(),scopeId=v.orgScopeId||recScope(v.sourceType,source)[0];requireValue(scopeId&&orgNode(scopeId),'An accountable location is required.');const existing=S.tasks.find(t=>t.boardDecisionKey===v.key&&t.status!=='Completed');if(existing){actions['task-detail']({dataset:{id:existing.id}});return;}openDialog('Assign exception follow-up','Confirm who is accountable and when management will receive an update.',`<div class="stack">${input('title','Action title','Review '+v.title,'text','required maxlength="200"')}${select('owner','Accountable owner',CS_SEED.people,CS_SEED.people.includes(v.owner)?v.owner:CS_SEED.people[0])}${input('due','Due date',addDays(S.asOf,7),'date',`required min="${S.asOf}"`)}${area('description','Expected outcome',v.ask+'\n'+v.why,'maxlength="2500"')}<p class="br-muted">Source: ${e(v.sourceId)} · ${e(orgName(scopeId))}</p></div>`,'Create follow-up',form=>{const data=values(form),r=recRead(v.sourceType,v.sourceId);requireValue(r&&recInScope(v.sourceType,r,originalScope),'The source is no longer available in the original scope.');requireValue(selectedScope()===originalScope,'Navigation scope changed. Open the action again from the intended scope.');requireValue(data.title.trim().length>=3&&data.description.trim().length>=10,'Enter a useful action title and expected outcome.');requireValue(CS_SEED.people.includes(data.owner),'Choose a known owner.');validDate(data.due,'Due date',false);requireValue(data.due>=S.asOf,'Due date cannot precede the snapshot.');requireValue(!S.tasks.some(t=>t.boardDecisionKey===v.key&&t.status!=='Completed'),'An open follow-up already exists for this exception.');const t={id:uid('ACT'),title:data.title.trim(),description:data.description.trim(),kind:'Remediation',owner:data.owner,ownerId:recUserId(data.owner),due:data.due,status:'Open',orgScopeId:scopeId,ref:v.sourceId,sourceRef:{type:v.sourceType,id:v.sourceId},route:v.sourceRoute,boardDecisionKey:v.key};S.tasks.unshift(t);audit('Assigned report exception follow-up '+t.title,v.sourceId,recActor().name);if(window.CS_V28_EVENTS)window.CS_V28_EVENTS.emit({id:'notification-'+t.id,type:'program',title:'New exception follow-up: '+t.title,body:t.description,sourceRoute:'work',sourceId:t.id,orgScopeId:scopeId,severity:'warning',recipient:t.owner,actor:recActor().name,due:t.due});render();toast('Follow-up assigned and linked to the source record.');});}
});
document.addEventListener('input',ev=>{const el=ev.target,d=S.reportDraft;if(!d)return;if(el.matches('[data-br-draft]')){d[el.dataset.brDraft]=el.value;save();}if(el.matches('[data-br-decision]')){const i=Number(el.dataset.brDecision),part=el.dataset.part;if(d.decisions?.[i]&&['title','kind','owner','due','sourceId','rationale'].includes(part)){d.decisions[i][part]=el.value;save();}}});
document.addEventListener('change',ev=>{const el=ev.target,d=S.reportDraft;if(!d)return;if(el.matches('[data-br-coverage]')){d.coverageAcknowledged=el.checked;save();}if(el.matches('[data-br-draft]')){d[el.dataset.brDraft]=el.value;save();}if(el.matches('[data-br-decision]')){const i=Number(el.dataset.brDecision),part=el.dataset.part;if(d.decisions?.[i]&&['title','kind','owner','due','sourceId','rationale'].includes(part)){d.decisions[i][part]=el.value;save();}}});
Object.assign(window.CS_JOURNEYS,{'insight-detail':brDetailView,'report-builder':brReportBuilder,'report-pack':brReportPackView});
window.CLEAR_SIGHT_BOARD=Object.freeze({version:'2.8',snapshot:()=>clone(reportData()),decisions:()=>clone(brDecisionItems(reportData())),draftIssues:()=>S.reportDraft?brDraftIssues(brEnsureDraft()):['No report in preparation.']});
